import React, { useEffect, useState } from "react";
import "./BuyHouseList.css"; // reuse same styles

function formatCurrencyINR(n) {
  if (n == null || isNaN(n)) return "—";
  const v = Number(n);
  if (v >= 1e7) return `₹${(v / 1e7).toFixed(2)} Cr`;
  if (v >= 1e5) return `₹${(v / 1e5).toFixed(2)} L`;
  return `₹${v.toLocaleString("en-IN")}`;
}

export default function BuyLandList() {
  const [lands, setLands] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");
  const [revealed, setRevealed] = useState({});
  const [predicted, setPredicted] = useState({});
  const [predicting, setPredicting] = useState({});
  const [lightboxSrc, setLightboxSrc] = useState(null);

  const openLightbox = (src) => setLightboxSrc(src);
  const closeLightbox = () => setLightboxSrc(null);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      setErr("");
      try {
        const res = await fetch(`${process.env.REACT_APP_BACKEND_URL}/buy/lands`);
        if (!res.ok) throw new Error("Failed to load");
        const data = await res.json();
        setLands(data);
      } catch (e) {
        setErr("Unable to fetch land listings. Please try again.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") closeLightbox(); };
    if (lightboxSrc) window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [lightboxSrc]);

  const doPredict = async (land) => {
    // Adjust payload to your land predict API’s expected schema
    const payload = {
      Area_sqft: land.area_sqft || 0,
      zoning: land.zoning || "",
      latitude: land.latitude || 0,
      longitude: land.longitude || 0,
      // Amenities (optional defaults)
      waterApplicable: "notApplicable",
      waterDistance: 0,
      roadApplicable: "notApplicable",
      roadDistance: 0,
      schoolApplicable: "notApplicable",
      schoolDistance: 0,
      railwayApplicable: "notApplicable",
      railwayDistance: 0,
      busApplicable: "notApplicable",
      busDistance: 0
    };

    setPredicting((p) => ({ ...p, [land.id]: true }));
    try {
      const res = await fetch(`${process.env.REACT_APP_BACKEND_URL}/predict/land`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      if (!res.ok) throw new Error("Predict failed");
      const data = await res.json();
      setPredicted((p) => ({ ...p, [land.id]: Number(data.price) }));
    } catch (e) {
      setPredicted((p) => ({ ...p, [land.id]: null }));
      alert("Prediction failed. Please try again.");
    } finally {
      setPredicting((p) => ({ ...p, [land.id]: false }));
    }
  };

  if (loading) return <div className="buy-loading">Loading land listings...</div>;
  if (err) return <div className="buy-error">{err}</div>;
  if (!lands.length) return <div className="buy-empty">No land listings found.</div>;

  return (
    <div className="buy-root">
      {lands.map((l) => {
        const isRevealed = revealed[l.id];
        const pred = predicted[l.id];
        const actual = l.actualPrice != null ? Number(l.actualPrice) : null;
        const showDeal =
          typeof pred === "number" && typeof actual === "number" && pred < actual;

        return (
          <div className="buy-card" key={l.id}>
            <div className="buy-card-left">
              <div className="buy-thumb">
                {l.image ? (
                  <button
                    type="button"
                    className="thumb-click"
                    onClick={() =>
                      openLightbox(`${process.env.REACT_APP_BACKEND_URL}${l.image}`)
                    }
                    aria-label="View full image"
                  >
                    <img
                      src={`${process.env.REACT_APP_BACKEND_URL}${l.image}`}
                      alt=""
                    />
                  </button>
                ) : (
                  <div className="no-img">No Image</div>
                )}
                <span className="badge">Land</span>
              </div>
            </div>

            <div className="buy-card-mid">
              <div className="buy-title">
                {l.zoning || "Land"} in {l.city || l.district || l.state || l.location || "—"}
              </div>

              <div className="buy-meta">
                <div className="price">{formatCurrencyINR(actual)}</div>
                <div className="meta-item">{l.area_sqft || "—"} sq.ft</div>
                {l.zoning && <div className="meta-item">{l.zoning}</div>}
              </div>

              {pred != null && (
                <div className={`predict-row ${showDeal ? "deal-ok" : "deal-warn"}`}>
                  <span>Model price: {formatCurrencyINR(pred)}</span>
                  {showDeal ? (
                    <span className="deal good">Good deal</span>
                  ) : (
                    <span className="deal warn">Above model</span>
                  )}
                </div>
              )}

              {(l.location || l.city || l.district || l.state) && (
                <div className="location-row">
                  <span className="pin">📍</span>
                  <span className="loc-text">
                    {l.location || [l.city, l.district, l.state].filter(Boolean).join(", ")}
                  </span>
                </div>
              )}
            </div>

            <div className="buy-card-right">
              <div className="btn-row">
                <button
                  className="btn contact"
                  onClick={() =>
                    setRevealed((r) => ({ ...r, [l.id]: !isRevealed }))
                  }
                >
                  {isRevealed ? l.contact || "NA" : "Contact"}
                </button>

                {/* Hide this button if you don’t have /predict/land */}
                <button
                  className="btn predict"
                  disabled={predicting[l.id]}
                  onClick={() => doPredict(l)}
                >
                  {predicting[l.id] ? "Predicting..." : "Predict"}
                </button>
              </div>
            </div>
          </div>
        );
      })}

      {/* Lightbox modal */}
      {lightboxSrc && (
        <div
          className="lb-overlay"
          onClick={closeLightbox}
          role="dialog"
          aria-modal="true"
        >
          <div className="lb-content" onClick={(e) => e.stopPropagation()}>
            <button className="lb-close" onClick={closeLightbox} aria-label="Close">
              ×
            </button>
            <img src={lightboxSrc} alt="" />
          </div>
        </div>
      )}
    </div>
  );
}
